INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 34, 'theory', 'Quiz: tokio — time and select!');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 0, 'How does tokio::time::sleep differ from std::thread::sleep inside an async task?', '["No difference", "sleep returns a future and gives the thread to other tasks, while thread::sleep blocks the thread", "thread::sleep is more precise", "sleep works only in tests"]', 1, 'A blocking sleep puts the thread to sleep along with all the tasks on it. Tokio''s sleep frees the thread while waiting.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 1, 'When does the first tick() of tokio::time::interval fire?', '["After one period", "Immediately, without waiting", "After the second call", "Never: it needs a reset"]', 1, 'The first tick of an interval returns at once; after that, at a constant period.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 2, 'What does timeout(d, fut) return if the future did not finish within d?', '["Ok(None)", "Err(Elapsed), and the future is dropped", "A panic", "A default value"]', 1, 'The result is Err(Elapsed); the inner future stops running.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 3, 'What happens to the losing branches of select!?', '["They keep running in the background", "Their futures are dropped", "They run later, in turn", "They cause a panic"]', 1, 'The first future to complete wins and the rest are dropped — hence the cancel safety requirement.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 34, 4, 'Why put biased; at the start of select!?', '["To speed it up", "So that branches are polled strictly in order, not randomly", "To enable logging", "To disable else"]', 1, 'By default the polling order is random, for fairness. biased; makes the order deterministic.');
